const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const marovoay = ee.Geometry.Point(46.634, -16.009); // Approximate location of Marovoay, Madagascar
  const buffer_size = 5000; // 5 km buffer around the point to define the area of interest
  const aoi = marovoay.buffer(buffer_size);

  // Date ranges for each comparison point
  // Allowing a wider window for Sentinel-1 as it doesn't have daily coverage everywhere.
  const date1_start = '2017-01-01';
  const date1_end = '2017-01-31'; // Original request Jan 18, 2017
  const date2_start = '2020-01-01';
  const date2_end = '2020-01-31'; // Original request Jan 27, 2020

  const scale = 30; // Sentinel-1 resolution is 10m, but 30m is a good balance for regional stats and performance.

  // Function to get and process Sentinel-1 GRD images
  const getWaterExtent = (startDate, endDate, geometry) => {
    let collection = ee.ImageCollection('COPERNICUS/S1_GRD')
      .filterBounds(geometry)
      .filterDate(startDate, endDate)
      .filter(ee.Filter.listContains('transmitterReceiverPolarisation', 'VV'))
      .filter(ee.Filter.eq('instrumentMode', 'IW'))
      .filter(ee.Filter.eq('orbitProperties_pass', 'DESCENDING')); // Use DESCENDING pass for consistency

    // Check if collection is empty
    const collectionSize = collection.size().getInfo();
    if (collectionSize === 0) {
      return { image: null, size: 0 };
    }

    // Apply speckle filtering by taking the mean of the collection for the period
    const composite = collection.select('VV').mean();

    // Convert to dB
    const dbImage = ee.Image.constant(10).multiply(composite.log10());

    // Simple thresholding for water (water has very low backscatter)
    // Threshold of -18 dB is commonly used for open water.
    const water = dbImage.lt(-18).rename('water_mask'); // 1 for water, 0 for land

    return { image: water, size: collectionSize };
  };

  // 2. Data Acquisition & Check for 2017
  let s1_2017 = getWaterExtent(date1_start, date1_end, aoi);
  if (s1_2017.size === 0) {
    console.log(`2017 Images: 0. No Sentinel-1 data found for ${date1_start} to ${date1_end}.`);
    console.log('C1');
    return;
  }
  const water_2017_mask = s1_2017.image;

  // 3. Data Acquisition & Check for 2020
  let s1_2020 = getWaterExtent(date2_start, date2_end, aoi);
  if (s1_2020.size === 0) {
    console.log(`2020 Images: 0. No Sentinel-1 data found for ${date2_start} to ${date2_end}.`);
    console.log('C1');
    return;
  }
  const water_2020_mask = s1_2020.image;

  // 4. Calculate Water Extent (Area in km^2) for 2017
  // Multiply by pixel area to get area in square meters, then divide by 1e6 for km^2
  const water_area_2017 = water_2017_mask.multiply(ee.Image.pixelArea()).divide(1e6);

  const stats_2017 = water_area_2017.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: aoi,
    scale: scale,
    maxPixels: 1e9,
    crs: 'EPSG:4326', // Use WGS84 for consistency
    crsTransform: [1, 0, 0, 0, 1, 0] // Reset transform
  });

  let area_2017_km2 = stats_2017.get('water_mask').getInfo();

  // Validate area_2017_km2
  if (area_2017_km2 === null || isNaN(area_2017_km2)) {
    console.log(`2017 Images: ${s1_2017.size}`);
    console.log('Calculation failed for 2017 water extent.');
    console.log('C3');
    return;
  }

  // Check for C2 (No valid pixels for water)
  if (area_2017_km2 === 0) {
    const pixelCount = water_2017_mask.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: aoi,
      scale: scale,
      maxPixels: 1e9
    }).get('water_mask').getInfo();
    if (pixelCount === 0) {
      console.log(`2017 Images: ${s1_2017.size}. No valid pixels in AOI after processing for 2017.`);
      console.log('C2');
      return;
    }
  }


  // 5. Calculate Water Extent (Area in km^2) for 2020
  const water_area_2020 = water_2020_mask.multiply(ee.Image.pixelArea()).divide(1e6);

  const stats_2020 = water_area_2020.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: aoi,
    scale: scale,
    maxPixels: 1e9,
    crs: 'EPSG:4326',
    crsTransform: [1, 0, 0, 0, 1, 0]
  });

  let area_2020_km2 = stats_2020.get('water_mask').getInfo();

  // Validate area_2020_km2
  if (area_2020_km2 === null || isNaN(area_2020_km2)) {
    console.log(`2020 Images: ${s1_2020.size}`);
    console.log('Calculation failed for 2020 water extent.');
    console.log('C3');
    return;
  }

  // Check for C2 (No valid pixels for water)
  if (area_2020_km2 === 0) {
    const pixelCount = water_2020_mask.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: aoi,
      scale: scale,
      maxPixels: 1e9
    }).get('water_mask').getInfo();
    if (pixelCount === 0) {
      console.log(`2020 Images: ${s1_2020.size}. No valid pixels in AOI after processing for 2020.`);
      console.log('C2');
      return;
    }
  }

  // 6. Validation & Final Answer
  console.log(`2017 Images: ${s1_2017.size}, Water extent: ${area_2017_km2.toFixed(2)} km^2`);
  console.log(`2020 Images: ${s1_2020.size}, Water extent: ${area_2020_km2.toFixed(2)} km^2`);

  if (area_2020_km2 > area_2017_km2) {
    console.log('A');
  } else {
    console.log('B');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
